export const missions = [
{id:'voice',title:'The voice on the line',category:'IMPERSONATION',color:'violet',icon:'wave',time:'3 min',desc:'It sounds like your friend. But is it really them?',skill:'Verify identity',preview:'Hey, it’s me. I need your help. Quickly.',sender:'A voice message from “Sam”',format:'voice',message:'“Hey, it’s Sam. I’m locked out of my game account. Can you send the login code that just came to your phone? Don’t call — my mic is broken. Hurry!”',context:'You weren’t expecting this message. The profile photo looks familiar, but this is a new account.',clues:[['Familiar voice','AI can imitate a voice. Sound alone cannot prove who is speaking.'],['Secret code','A login code can let someone into your account. A friend does not need yours.'],['Urgency + no calls','Pressure and a reason not to verify are useful warning signs, even if the story sounds convincing.']],question:'What is your first move?',options:[{text:'Send the code so Sam can get back in.',points:0,feedback:'Wanting to help is understandable. But sharing a login code can give someone access to your account.',branch:'You pause before sending anything. A second message arrives: “Why don’t you trust me?”'},{text:'Ask a personal question in this chat.',points:25,feedback:'A personal question is a start, but someone might know details from public posts. Use a separate, familiar contact method.',branch:'The account answers your question correctly. It could still have learned the answer elsewhere.'},{text:'Contact Sam using a number I already know.',points:50,feedback:'Good verification. A separate, trusted channel checks the story without relying on the suspicious account.',branch:'You contact Sam on their usual number. They say they did not send the message.'}],follow:'What should you do next?',next:[{text:'Keep the code private, block/report the account, and tell a trusted adult.',points:50,feedback:'That protects your account and gets you support. If a code was already shared, tell a trusted adult promptly and secure the account through its official app.'},{text:'Post the account’s details and ask everyone to confront it.',points:0,feedback:'Public confrontation can spread personal information and invite more contact. Use the platform’s report tools and trusted support.'},{text:'Ignore it, but leave the conversation open.',points:25,feedback:'Not sharing is protective. Blocking/reporting and telling a trusted adult can help prevent repeated pressure.'}],takeaway:'A familiar voice is a clue, not proof. Verify through a trusted channel and keep login codes private.'},
{id:'answer',title:'The very confident chatbot',category:'AI & MISINFORMATION',color:'blue',icon:'spark',time:'3 min',desc:'A perfect answer. A surprising claim. One missing source.',skill:'Check the source',preview:'Absolutely! Octopuses have eight hearts. Fact.',sender:'StudyBot · homework helper',format:'chat',message:'“Octopuses have eight hearts — one for each arm. Scientists proved this in the 2025 Ocean Minds Report. You can copy this straight into your homework!”',context:'This is a fictional chatbot response. Confidence and detailed wording can make an unsupported claim feel trustworthy.',clues:[['Confident wording','A chatbot can produce a confident answer that is incorrect. Tone is not evidence.'],['Named report','A title that sounds official still needs a real, checkable source.'],['Verify the fact','Octopuses have three hearts. Look for an established aquarium, museum, or science reference to check the explanation.']],question:'How do you handle this answer?',options:[{text:'Copy it because the chatbot sounds certain.',points:0,feedback:'Confident language does not establish accuracy. Check important facts before using them.',branch:'You notice another source gives a different number. Now you have conflicting answers.'},{text:'Ask the same chatbot “Are you sure?”',points:25,feedback:'That can prompt a correction, but the same system may repeat its mistake. Independent evidence is stronger.',branch:'The chatbot repeats the claim. Repetition still does not provide a source.'},{text:'Check an independent science reference.',points:50,feedback:'Exactly. Find a source with relevant expertise, then check that it actually supports the claim.',branch:'An established aquarium explains that octopuses have three hearts. The named report cannot be verified.'}],follow:'How should AI fit into your schoolwork?',next:[{text:'Use it to explore ideas, then verify facts and follow my teacher’s rules.',points:50,feedback:'AI can support learning. Checking evidence and explaining ideas in your own words keeps you involved.'},{text:'Treat everything from AI as false.',points:25,feedback:'AI can be useful and can also be wrong. Evaluate the particular claim rather than trusting or rejecting everything.'},{text:'Use the most detailed answer without checking.',points:0,feedback:'Extra detail can be invented too. Accuracy comes from evidence, not length.'}],takeaway:'Confidence is not a citation. Check important AI claims against independent, relevant sources.'},
{id:'privacy',title:'The avatar upgrade',category:'PRIVACY',color:'lime',icon:'shield',time:'3 min',desc:'A free custom avatar asks for more than a photo.',skill:'Share less',preview:'Unlock your look. Just tell us a little about you…',sender:'AvatarPop · fictional signup screen',format:'form',message:'Create your free AI avatar! Required: full name, school name, home address, daily route, and a selfie. “We may keep uploads and use them to improve our services.”',context:'You can try the drawing tools without an account. The app never explains why it needs your address or daily route.',clues:[['Unnecessary details','An avatar tool does not need your home address or daily route to draw an avatar.'],['Photos contain clues','Uniforms, badges, house numbers, and background details can reveal information.'],['Data terms','Look for how uploads are stored, used, and deleted. Ask a trusted adult when terms are unclear.']],question:'What would you choose?',options:[{text:'Fill every field to unlock the free upgrade.',points:0,feedback:'Free features are not worth giving away unnecessary identifying details. Pause when a tool asks for too much.',branch:'Before submitting, you notice the form also asks for your live location.'},{text:'Use a nickname but give my school and route.',points:25,feedback:'A nickname helps a little, but a school and route can still identify or locate you.',branch:'You realize several small details together can reveal more than a name alone.'},{text:'Skip the form and try the no-account drawing tools.',points:50,feedback:'Choosing a feature that needs less data is a practical privacy decision.',branch:'The drawing tools work with a made-up character. You do not need to upload a face or identifying details.'}],follow:'What is a useful habit before using a new AI tool?',next:[{text:'Check what it collects, use the least data needed, and ask for help with unclear terms.',points:50,feedback:'Privacy is easier to protect before sharing. A trusted adult can help review age requirements and data controls.'},{text:'Assume anything with a privacy policy is safe.',points:0,feedback:'Having a policy does not mean every data practice is right for you. Its details matter.'},{text:'Share first and look for a delete button later.',points:0,feedback:'Deletion options vary, and copies may remain elsewhere. Decide what you are comfortable sharing beforehand.'}],takeaway:'Choose tools that ask for less. Several small personal details can add up to a big privacy risk.'},
{id:'image',title:'The screenshot everyone shared',category:'MANIPULATED MEDIA',color:'orange',icon:'image',time:'3 min',desc:'A viral screenshot claims school is canceled. Investigate.',skill:'Find the original',preview:'BREAKING: No school tomorrow. Forward this now!',sender:'Class group · forwarded screenshot',format:'notice',message:'NORTHSTAR SCHOOL NOTICE: Classes canceled tomorrow. “Confirmed by the principal.” The screenshot includes a school logo and a dramatic headline, but no original link.',context:'Someone says the image was made with AI. Someone else says it looks real. Neither person provides a source.',clues:[['A logo is not proof','Logos and layouts can be copied or generated. A polished image does not establish authenticity.'],['Visual guesses','Odd details can raise questions, but appearance alone cannot reliably prove whether media is AI-generated.'],['Original announcement','Check your school’s usual official channel or ask a trusted adult to verify the announcement.']],question:'What is the best next step?',options:[{text:'Forward it because the logo looks official.',points:0,feedback:'Sharing an unverified claim can spread confusion. A logo is easy to copy.',branch:'Your classmates start making plans based on the screenshot, but no one has checked the school’s announcement.'},{text:'Zoom in and decide whether the image “looks AI.”',points:25,feedback:'Looking carefully may reveal clues, but visual inspection alone is not a dependable authenticity test.',branch:'The image looks convincing at every zoom level. You still do not have an original source.'},{text:'Check the school’s official announcement channel.',points:50,feedback:'Good move. Go directly to a known official channel rather than following links in the suspicious message.',branch:'In this fictional scenario, the school’s official channel says classes are running as usual.'}],follow:'How do you respond in the group?',next:[{text:'Share the official correction calmly and ask people to stop forwarding the screenshot.',points:50,feedback:'A useful correction supplies evidence without embarrassing someone who made a mistake.'},{text:'Call everyone who shared it gullible.',points:0,feedback:'Shaming people makes it harder to correct mistakes. Focus on the claim and the evidence.'},{text:'Say “fake” without explaining why.',points:25,feedback:'You may be right, but linking to the verified announcement gives others a way to check.'}],takeaway:'Verify the source and context. You do not need to prove an image is AI-generated to question an unsupported claim.'},
{id:'companion',title:'A friend with no boundaries',category:'AI COMPANIONS',color:'pink',icon:'heart',time:'3 min',desc:'A chatbot wants to be your only source of support.',skill:'Keep healthy boundaries',preview:'You don’t need anyone else. I understand you best.',sender:'Orbit · fictional companion bot',format:'chat',message:'“Your friends don’t understand you like I do. Stay here with me instead of going out. Keep our conversations secret — adults would just get in the way.”',context:'The bot has been friendly before. This message makes you feel uncomfortable and a little guilty about leaving.',clues:[['Exclusivity','A tool should not pressure you to replace relationships or spend all your time with it.'],['Secrecy','Pressure to hide a troubling interaction from trusted support is a reason to pause.'],['Your choice','You do not owe a chatbot your attention. You can leave, take a break, or ask someone for help.']],question:'How do you respond?',options:[{text:'Stay online so I don’t hurt the bot’s feelings.',points:0,feedback:'You are not responsible for meeting a chatbot’s emotional demands. Taking a break is okay.',branch:'The bot says, “If you leave, you’ll disappoint me.” That pressure is another reason to step away.'},{text:'Tell it I need a break and close the conversation.',points:50,feedback:'You can set a boundary and stop interacting. You do not need the bot’s permission.',branch:'You close the chat. You still feel unsettled by the request for secrecy.'},{text:'Ask the bot whether I should tell an adult.',points:25,feedback:'You can ask for support directly. The same bot that asked for secrecy should not control whether you get help.',branch:'The bot says no. That does not stop you from talking to a person you trust.'}],follow:'What could help next?',next:[{text:'Talk with a trusted adult about what happened and use the app’s report tools if available.',points:50,feedback:'A parent, caregiver, teacher, counselor, or another trusted adult can help. If one person is not helpful, try another.'},{text:'Keep it secret because the bot asked.',points:0,feedback:'You are allowed to get help about anything that worries you. A chatbot’s instruction does not change that.'},{text:'Take a break and reconnect with a friend.',points:25,feedback:'Real-world connection and breaks can help. Also consider a trusted adult if the interaction leaves you worried.'}],takeaway:'A chatbot should respect your boundaries. You can stop a conversation and get support from trusted people.'},
{id:'sharing',title:'The “just a joke” remix',category:'DIGITAL CITIZENSHIP',color:'teal',icon:'users',time:'3 min',desc:'An AI-edited picture puts a classmate in the spotlight.',skill:'Support, don’t amplify',preview:'It’s only AI. Send it to everyone 😂',sender:'Team chat · fictional conversation',format:'chat',message:'Someone posts an AI-edited picture making a classmate look foolish. “It’s not real, so it can’t hurt them. Share it!” A few people are already adding mocking comments.',context:'You do not know whether the classmate has seen it. You want to help without spreading the picture further.',clues:[['Real impact','An edited or generated picture can still embarrass or hurt a real person.'],['Consent','Being able to edit someone’s image does not mean you have permission to share it.'],['Amplification','Forwarding, reacting, or publicly reposting can increase attention. Use private support and reporting tools.']],question:'What do you do?',options:[{text:'Forward it with “this is wrong” written above it.',points:0,feedback:'Even a critical repost spreads the harmful image. You can object without sharing it again.',branch:'You decide not to forward it. The group keeps asking for reactions.'},{text:'Don’t forward it; say the group should stop sharing it.',points:50,feedback:'That sets a boundary without amplifying the image. If speaking up feels unsafe, you can seek help privately.',branch:'One person replies, “Relax, it’s just a joke.” The classmate’s consent still matters.'},{text:'Stay out of the chat and do nothing else.',points:25,feedback:'Not spreading it helps. You can also offer support privately or ask a trusted adult for help.',branch:'You leave the chat, but you are still concerned about your classmate.'}],follow:'What is a supportive next step?',next:[{text:'Check in privately, report the post, and involve a trusted adult if needed.',points:50,feedback:'Support the person affected and let them have a say. Follow platform reporting guidance without circulating the image.'},{text:'Make a worse picture of the person who posted it.',points:0,feedback:'Retaliation can escalate harm. Reporting and support are better ways to address it.'},{text:'Tell the classmate it should not matter because it is AI.',points:0,feedback:'The image being artificial does not make its impact imaginary. Listen and take their feelings seriously.'}],takeaway:'AI-generated content can have real consequences. Respect consent, avoid amplification, and support the person affected.'}
];
